import { useMemo } from 'react';

import { TableDataType } from 'components/Table/types';
import { useBffData } from 'hooks';

import {
  PERFORMANCE_TOOL_MARKET_SHARE_UPDATE_STATUS_BFF_ID,
  PERFORMANCE_TOOL_UPDATE_STATUS_COMPONENT_ID,
} from '../../../../constants';

const EMPTY_TABLE_DATA: TableDataType = { header: [], rows: [] };

export const useSourceStatusData = () => {
  const bffResult = useBffData({
    id: PERFORMANCE_TOOL_MARKET_SHARE_UPDATE_STATUS_BFF_ID,
    kpiGroup: 'market_share',
    skipMainFilters: true,
  });

  const tableData = useMemo(() => {
    const componentData =
      bffResult.data?.[PERFORMANCE_TOOL_UPDATE_STATUS_COMPONENT_ID];

    if (!componentData || componentData.empty) {
      return EMPTY_TABLE_DATA;
    }

    return componentData as TableDataType;
  }, [bffResult.data]);

  const empty = useMemo(() => {
    const componentData =
      bffResult.data?.[PERFORMANCE_TOOL_UPDATE_STATUS_COMPONENT_ID];

    if (bffResult.loading || bffResult.error) {
      return false;
    }

    return (
      componentData?.empty === true ||
      !tableData.rows?.length ||
      tableData.rows.every((group) => group.length === 0)
    );
  }, [bffResult.data, bffResult.error, bffResult.loading, tableData.rows]);

  return {
    data: tableData,
    loading: bffResult.loading,
    error: bffResult.error,
    empty,
  };
};
